import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1176, own='cte_99.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 756 Community Emergency Response Team (CERT) ----
H("756.d.16",3,"After a tornado, a CERT volunteer fills out a damage form listing addresses, injuries and resources used. This researches the:","documentation required during a disaster response",["menu for a picnic","sports scores","bus schedule"],"Disaster response is documented for coordination and records.")
H("756.d.16",4,"Documentation during a disaster response is important because it:","records actions, needs and resources for responders and officials",["replaces all training","hides mistakes","slows rescue work"],"Records support coordination and later review.")
H("756.d.1.A",3,"A neighborhood CERT member helps hand out flyers before storm season, checks on neighbors during the storm and assists with cleanup afterward. This compares CERT roles:","before, during and after a disaster",["only after","only during","only before"],"CERT roles span all phases.")
H("756.d.1.A",4,"Before a disaster, a typical CERT role is to:","teach neighbors preparedness and help plan",["lead the national response","give legal rulings","drive ambulances"],"Preparedness education is a CERT function.")
H("756.d.1.B",3,"A coastal CERT team trains for hurricanes while a plains team trains for tornadoes and wildfire. This analyzes how CERT members respond to:","hazards common to their area",["every hazard in the world","no hazards","only man-made hazards"],"Training is tailored to local hazards.")
H("756.d.1.B",4,"CERT training is adjusted to a community mainly because:","different areas face different likely hazards",["all areas are identical","hazards never change","training is optional"],"Local risks vary.")
H("756.d.1.C",3,"A volunteer learns that Texas law gives certain protection to trained disaster volunteers acting in good faith. This analyzes:","state and local laws that protect first responders",["traffic fines","school policies","tax breaks only"],"Laws protect responders acting within training.")
H("756.d.1.C",4,"A legal protection like a Good Samaritan law is meant to:","encourage people to help in emergencies without fear of unfair lawsuits",["punish helpers","prevent all aid","ban volunteers"],"It protects good-faith helpers.")
H("756.d.2.A",3,"A flood and a hurricane fall in one group and a chemical spill and a power-plant accident in another. This classifies disasters as:","natural and man-made",["fast and slow","loud and quiet","big and small"],"Disasters are natural or man-made.")
H("756.d.2.A",4,"Which is a man-made disaster?","a chemical plant explosion",["an earthquake","a drought","a hurricane"],"Industrial accidents are man-made.")
H("756.d.2.B",3,"A report says a wildfire started from a campfire left burning and spread because of high winds and dry brush. This identifies:","common causes of disasters",["rules of a game","school subjects","shop prices"],"Accidents, weather and human error cause disasters.")
H("756.d.2.B",4,"A disaster caused by weather conditions like heavy rain is a:","natural cause of disaster",["accidental spill","terror plot","software bug"],"Weather causes natural disasters.")
H("756.d.3.A",3,"CERT trainees list flying debris, downed power lines and contaminated water after a hurricane. These are:","potential hazards of a disaster",["benefits of a disaster","party supplies","fun activities"],"Disasters create many hazards.")
H("756.d.3.A",4,"Which hazard is commonly associated with a flood?","contaminated water",["snow","volcanic ash","rockfall only"],"Floodwater can be contaminated.")
H("756.d.3.B",3,"A team shuts off gas lines, secures loose furniture and moves stored chemicals to high shelves to limit damage. These are:","strategies used to manage hazards and reduce impact",["ways to cause hazards","ways to hide danger","ways to ignore risk"],"Mitigation reduces impact.")
H("756.d.3.B",4,"Anchoring a tall bookcase to the wall before an earthquake is an example of:","hazard mitigation",["a hazard","a response delay","ignoring risk"],"Securing items prevents injury.")
H("756.d.3.C",3,"A handout lists steps to take before, during and after a disaster, such as building a kit, sheltering and cleaning up safely. This summarizes:","measures taken before, during and after a disaster",["only recovery steps","only rumors","only cleaning"],"Preparedness spans phases.")
H("756.d.3.C",4,"Preparing an evacuation plan is a step taken:","before a disaster",["after the disaster","never","only during cleanup"],"Plans are made in advance.")
H("756.d.4.A",3,"A family draws their home's floor plan, marks two exits from every room and picks a meeting place outside. This is a:","fire response plan and evacuation route",["cooking plan","party plan","travel plan"],"Escape plans save lives.")
H("756.d.4.A",4,"A good home fire escape plan includes two ways out of each room and a:","meeting place outside",["parking lot map","list of recipes","TV schedule"],"Everyone should meet at a safe place.")
H("756.d.4.B",3,"A family prepares for a tornado by choosing a basement corner as the place to take cover. This is a response plan with a:","safe shelter location",["picnic area","game room","storage list"],"Shelter plans identify safe locations.")
H("756.d.4.B",4,"During a tornado warning at home without a basement, the safest place is usually:","an interior room on the lowest floor away from windows",["near a large window","outside","a car in the driveway"],"Interior rooms offer protection.")
H("756.d.5.A",3,"A volunteer packs bandages, gloves, gauze, tape, antiseptic wipes and a thermometer in a bag for the car. This identifies:","components of a first aid kit for home and vehicle",["tools for cooking","tools for painting","toys for kids"],"Kits hold basic medical supplies.")
H("756.d.5.A",4,"Which item belongs in a basic first aid kit?","sterile gauze pads",["a hammer only","a deck of cards","a phone cover"],"Gauze controls bleeding.")
H("756.d.5.B",3,"A list includes a flashlight, battery-powered radio, extra batteries and a whistle for a disaster kit. These are:","essential tools and supplies for disaster supply kits",["decorations","toys","furniture"],"Basic tools help in emergencies.")
H("756.d.5.B",4,"A battery-powered or hand-crank radio is a useful kit item because it lets you:","get emergency information if power is out",["play games","charge TVs","bake food"],"News and alerts continue.")
H("756.d.5.C",3,"A family packs water, canned food, a manual can opener, blankets, clothes and important papers. These are appropriate:","food, water, clothing and household items for a disaster kit",["luxuries","party items","office supplies"],"Kits must meet basic needs.")
H("756.d.5.C",4,"Emergency planners generally recommend storing about how much water per person per day?","one gallon",["one cup","ten gallons","none"],"One gallon per person per day.")
H("756.d.5.D",3,"In a drill, volunteers help fire crews with traffic, staging and search while keeping out of dangerous areas. This simulates:","assisting first responders in fire safety and search and rescue",["avoiding responders","acting alone","freelancing"],"CERT supports, not replaces, responders.")
H("756.d.5.D",4,"When assisting first responders, CERT volunteers should:","work under direction and within their training",["act independently","enter all hazards","ignore officers"],"Teamwork and limits keep people safe.")
H("756.d.5.E",3,"A volunteer reviews how the Volunteers in Police Service and CERT programs include fire safety in preparedness. This identifies:","fire safety components of disaster preparedness in volunteer programs",["unrelated topics","game rules","hobbies"],"Fire safety is part of preparedness.")
H("756.d.5.E",4,"Fire safety in a disaster preparedness program includes learning how to:","use extinguishers and shut off utilities safely",["start fires","fight large fires alone","avoid all training"],"Basic skills limit damage.")
H("756.d.6.A",3,"A CERT member walks through a neighbor's home checking smoke alarms, cords and cooking areas. This is a:","fire safety assessment",["party","remodel","yard sale"],"CERT teaches home fire safety.")
H("756.d.6.A",4,"A home fire safety assessment checks for:","working smoke alarms and overloaded outlets",["paint colors","furniture styles","TV channels"],"Alarms and electrical hazards matter.")
H("756.d.6.B",3,"Two volunteers enter a damaged building together so each can watch over the other. This is a safety precaution known as the:","buddy system",["solo rule","speed rule","loud rule"],"Buddies provide mutual protection.")
H("756.d.6.B",4,"Why do CERT members use the buddy system?","So they can watch out for each other and get help if needed",["to talk more","to carry less","to go faster"],"Two sets of eyes are safer.")
H("756.d.6.C",3,"CERT trainees predict where cleaning chemicals, paint, pesticides and fuels are stored in a home and in a business. This identifies:","locations of hazardous materials in homes and businesses",["locations of treasure","locations of parks","locations of stores"],"Knowing where hazmat is helps safety.")
H("756.d.6.C",4,"Which place in a home is most likely to store hazardous materials?","a garage or utility room",["a pillow","a bookshelf","a window sill"],"Garages hold chemicals and fuels.")
H("756.d.6.D",3,"A responder uses the limit, isolate, eliminate, separate approach to control a leak. This is the:","LIES method",["MAPS method","STOP method","SMART method"],"LIES: limit, isolate, eliminate, separate.")
H("756.d.6.D",4,"In the LIES method, the first 'L' stands for:","limit",["leave","listen","lift"],"Limit exposure to hazards.")
H("756.d.7.A",3,"A trainer explains that a small flame can spread when it reaches more fuel, air and heat. This explains how fires start and:","what perpetuates fires",["how to cook","how to paint","how to travel"],"Fires continue with fuel, heat and oxygen.")
H("756.d.7.A",4,"A fire is perpetuated when it has a continuing supply of:","fuel, heat and oxygen",["water","cold air","sand"],"All three keep burning.")
H("756.d.7.B",3,"CERT trainees name the three elements a fire needs to start and continue. This identifies:","the elements required for a fire",["parts of a kit","types of tools","ranks of volunteers"],"Remove one element to stop the fire.")
H("756.d.7.B",4,"Removing which element would stop a fire from burning?","oxygen, fuel or heat",["noise","light","color"],"Remove one leg of the triangle.")
H("756.d.7.C",3,"A volunteer lists the hazards of paper piles, gasoline and electrical panels in a garage. These are fire hazards of:","ordinary combustibles, flammable liquids and electrical equipment",["water sources","sports gear","decorations"],"Different materials create different hazards.")
H("756.d.7.C",4,"Storing gasoline in an unapproved container near a water heater is hazardous because:","flammable vapors can ignite",["gasoline sinks","it smells nice","it saves space"],"Vapors travel to ignition sources.")
H("756.d.7.D",3,"A CERT trainee learns that Class A involves wood and paper while Class B involves liquids. This describes:","the classes of fires",["the colors of hoses","the sizes of nozzles","the lengths of ladders"],"Classes guide agent selection.")
H("756.d.7.D",4,"A fire in an energized electrical panel is a:","Class C fire",["Class A fire","Class B fire","Class K fire"],"Class C = energized electrical.")
H("756.d.8.A",3,"A volunteer closes doors to confine a small room fire and shuts off nearby gas. These are:","fire containment techniques",["fire starters","fire sparks","fire fuels"],"Closing doors limits spread.")
H("756.d.8.A",4,"Closing a door behind you when leaving a burning room helps to:","slow fire spread and smoke movement",["speed the fire","feed the fire","add oxygen"],"A closed door contains the fire.")
H("756.d.8.B",3,"A trainee compares gasoline, kerosene and lighter fluid as materials that make fires start or spread faster. These are:","fire accelerants and fuels",["fire extinguishers","fire alarms","fire doors"],"Accelerants speed ignition.")
H("756.d.8.B",4,"An accelerant is a substance that:","helps a fire start or spread faster",["puts out fires","cools a fire","measures heat"],"Accelerants intensify fire.")
H("756.d.8.C",3,"A volunteer picks a dry chemical extinguisher for a gasoline fire rather than using water. This is selecting:","appropriate resources based on the fuel",["any tool","a random tool","no tool"],"Fuel type decides the agent.")
H("756.d.8.C",4,"Using water on a grease fire is dangerous because it can:","spread the burning grease",["cool it safely","smother it","stop it"],"Water splashes burning oil.")
H("756.d.8.D",3,"A trainee reads symbols, class ratings and instructions printed on an extinguisher. This explains information on:","fire extinguisher labels",["road signs","food labels","clothing tags"],"Labels list class, range and use.")
H("756.d.8.D",4,"An extinguisher label marked 'ABC' means it can be used on:","ordinary combustibles, flammable liquids and electrical fires",["only wood","only grease","only metals"],"Multipurpose rating.")
H("756.d.8.E",3,"A class compares water, dry chemical and CO2 extinguishers and labels the handle, pin, hose and gauge. This identifies:","types of extinguishers and components of a portable extinguisher",["types of ladders","types of tools","types of pumps"],"Parts and types matter.")
H("756.d.8.E",4,"The gauge on a pressurized extinguisher shows whether it is:","properly charged",["recently painted","lightweight","old"],"Gauge shows pressure.")
H("756.d.8.F",3,"A volunteer pulls the pin, aims low, squeezes the handle and sweeps on a practice fire. This simulates the use of:","a portable extinguisher using the PASS steps",["a hose line","an axe","a ladder"],"PASS describes extinguisher use.")
H("756.d.8.F",4,"The 'S' that follows 'Squeeze' in PASS stands for:","sweep",["stop","step","stand"],"Sweep side to side.")
H("756.d.8.G",3,"A CERT team reviews the local fire department's standard operating procedures for when volunteers may fight a small fire. This compares:","best practices for fire suppression based on local standard operating procedures",["unrelated rules","rumors","menus"],"Follow local SOPs.")
H("756.d.8.G",4,"A CERT volunteer should attempt to fight a fire only if the fire is:","small and an escape route is clear",["large and spreading","blocking all exits","filled with smoke"],"Safety first.")
H("756.d.9.A",3,"A volunteer evaluates the risks of a chemical that is toxic, flammable and corrosive. This identifies:","risks associated with characteristics of hazardous materials",["benefits of hazards","recipes","fashion trends"],"Characteristics determine risk.")
H("756.d.9.A",4,"A corrosive chemical is dangerous mainly because it can:","burn skin and eat through materials",["freeze items","make noise","change color only"],"Corrosives damage tissue.")
H("756.d.9.B",3,"A trainee sorts materials such as explosives, gases, flammable liquids and radioactive items into classes. This classifies hazardous materials according to the:","National Fire Protection Association or Department of Transportation system",["school system","grading system","telephone system"],"HazMat has standard classes.")
H("756.d.9.B",4,"Compressed gases, flammable liquids and explosives are examples of:","hazardous material classes",["fruit types","music types","tool types"],"Classes group hazards.")
H("756.d.9.C",3,"A diamond on a warehouse door has four colored squares with numbers. This is the:","NFPA 704 placard",["fire alarm","fire exit sign","parking permit"],"NFPA 704 communicates hazards.")
H("756.d.9.C",4,"The NFPA 704 diamond is designed to quickly show responders:","the health, fire and reactivity hazards of a material",["the building's age","the owner's name","the rent amount"],"It summarizes hazards.")
H("756.d.9.D",3,"On the NFPA diamond, blue stands for health, red for flammability and yellow for reactivity. This explains:","the meaning of hazardous material placard colors and numbers",["the color of cars","the flavor of foods","the weight of hoses"],"Colors map to hazard types.")
H("756.d.9.D",4,"On an NFPA 704 diamond, the red section indicates:","flammability",["health","reactivity","storage"],"Red = fire hazard.")
H("756.d.9.E",3,"A volunteer reads abbreviations and symbols such as 'W' with a line through it, meaning no water. These are common:","acronyms and symbols used by the NFPA",["road signs","menu items","game pieces"],"NFPA uses special symbols.")
H("756.d.9.E",4,"A white section on the NFPA diamond with a 'W' crossed out means the material:","reacts with water",["is safe in water","is non-flammable","glows"],"Avoid using water.")
H("756.d.10.A",3,"In a practice session, a volunteer places one hand on a manikin's forehead and lifts the chin to open the airway. This simulates:","the head tilt-chin lift method",["a log roll","a bandage wrap","a splint"],"Head tilt-chin lift opens the airway.")
H("756.d.10.A",4,"The head tilt-chin lift is used to:","open the airway of an unconscious patient",["stop bleeding","cool a patient","splint a bone"],"It moves the tongue away from the airway.")
H("756.d.10.B",3,"A trainee learns that bleeding can be arterial, venous or capillary. These are the:","primary types of bleeding",["types of burns","types of fractures","types of shock"],"Bleeding types differ.")
H("756.d.10.B",4,"The first step to control most external bleeding is to:","apply direct pressure to the wound",["wash it only","wait","apply heat"],"Direct pressure is first-line.")
H("756.d.10.C",3,"A student researches how a drop in blood flow can starve organs of oxygen. This explains the:","physiological effects of shock",["effects of boredom","effects of sunlight","effects of music"],"Shock deprives tissues of oxygen.")
H("756.d.10.C",4,"Shock is a life-threatening condition because it:","reduces blood flow to vital organs",["raises energy","improves circulation","cools the body"],"Poor perfusion harms organs.")
H("756.d.10.D",3,"A volunteer notices a victim with clammy skin, a rapid pulse and nausea. These are:","signs of shock",["signs of fitness","signs of hunger","signs of sleep"],"These suggest shock.")
H("756.d.10.D",4,"Which is a sign of shock?","pale, cool, clammy skin",["warm, dry skin","slow pulse always","flushed cheeks"],"Skin changes indicate shock.")
H("756.d.10.E",3,"In a drill, volunteers cover a manikin with a blanket, lay it flat and call for help. This simulates procedures for:","treating victims of shock",["ignoring victims","moving victims quickly","giving food"],"Treat for shock to stabilize.")
H("756.d.10.E",4,"A basic step in treating a person in shock is to:","keep them warm and call for emergency help",["give a large meal","let them walk","cool them rapidly"],"Warmth and EMS.")
H("756.d.10.F",3,"A volunteer elevates a patient's legs about 12 inches (if no injury prevents it) and covers them to keep warm. This is a technique for:","controlling symptoms of shock",["starting fires","removing debris","cooking food"],"Leg elevation helps blood flow.")
H("756.d.10.F",4,"Raising the legs of a shock victim may help because it:","helps blood return to vital organs",["slows breathing","causes injury","makes them cold"],"Elevation shifts blood to core.")
H("756.d.10.G",3,"A trained volunteer gives chest compressions and rescue breaths on a manikin at the correct rate and depth. This demonstrates:","cardiopulmonary resuscitation (CPR)",["bandaging","splinting","burn care"],"CPR maintains circulation.")
H("756.d.10.G",4,"Hands-only CPR compressions for an adult are given at a rate of about:","100 to 120 per minute",["20 per minute","60 per minute","200 per minute"],"AHA recommends 100–120.")
H("756.d.10.H",3,"A volunteer turns on a trainer unit, attaches pads and follows voice prompts. This demonstrates the use of an:","automated external defibrillator (AED)",["fire extinguisher","hose line","splint kit"],"AEDs deliver a shock when advised.")
H("756.d.10.H",4,"An AED is used on a person who:","is unresponsive and not breathing normally",["has a headache","has a cut","is hungry"],"AEDs treat cardiac arrest.")
H("756.d.11.A",3,"After a flood, volunteers wash hands with soap or sanitizer before eating and set up a handwashing station. This explains steps to maintain:","proper hygiene during a disaster",["poor hygiene","no hygiene","bad habits"],"Hygiene prevents disease.")
H("756.d.11.A",4,"During a disaster, the most effective way to prevent spreading illness is to:","wash hands with soap and clean water",["avoid all water","share utensils","skip washing"],"Handwashing prevents infection.")
H("756.d.11.B",3,"A camp crew buries human waste away from water sources and bags trash. This explains how to dispose of:","bacterial sources and waste during a disaster",["clean water","fresh food","new tools"],"Proper disposal prevents contamination.")
H("756.d.11.B",4,"Human waste during a disaster should be disposed of:","away from water sources and living areas",["in a stream","beside the camp","anywhere"],"Prevents contamination.")
H("756.d.11.C",3,"A team tests a filter and treats a water sample with purification tablets. This tests the use of a:","water purification system",["air purifier","oil filter","radio"],"Purification makes water safer to drink.")
H("756.d.11.C",4,"If no purification system is available, one safe method to treat water is to:","boil it for at least one minute",["let it sit in the sun briefly","add sugar","freeze it"],"Boiling kills most pathogens.")
H("756.d.12.A",3,"At a mass-casualty event, a volunteer quickly checks breathing, circulation and mental status to sort victims by priority. This is the concept of:","simple triage and rapid treatment (START)",["simple cleaning","slow transport","random sorting"],"START sorts quickly.")
H("756.d.12.A",4,"Triage means to:","sort victims by urgency of treatment",["treat everyone equally","move victims quickly","avoid treating anyone"],"Triage prioritizes care.")
H("756.d.12.B",3,"A disaster plan lists triage, treatment, transport and documentation as parts of medical operations. These are:","major sub-functions of disaster medical operations",["unrelated tasks","extra jobs","hobbies"],"Medical ops have sub-functions.")
H("756.d.12.B",4,"Which is a sub-function of disaster medical operations?","treatment of patients",["fundraising","decorating","sports"],"Treatment is a core function.")
H("756.d.12.C",3,"A team chooses a triage area close to the incident but away from hazards, with room and shelter. This selects and evaluates:","a designated triage area based on proximity to the incident",["a parking lot","a store","a school"],"Triage sites must be near but safe.")
H("756.d.12.C",4,"A triage area should be located:","near the incident yet safe from hazards",["inside the hazard","far from the scene","behind locked doors"],"Balance proximity and safety.")
H("756.d.12.D",3,"A volunteer checks that ambulances can reach the triage area and leave easily. This evaluates the area for:","accessibility by transportation",["scenic views","parking fees","decorations"],"Transport access is crucial.")
H("756.d.12.D",4,"When choosing a triage site, planners should confirm it has:","clear routes for ambulances to enter and exit",["only footpaths","no road access","only one narrow lane"],"Access speeds transport.")
H("756.d.12.E",3,"Victims needing immediate care, delayed care and those who have died are sent to separate areas. This assigns:","triage areas for immediate care, delayed care and morgue operations",["random areas","one area for all","no areas"],"Separate areas by category.")
H("756.d.12.E",4,"In triage, 'immediate' victims are those who:","need lifesaving treatment right away",["can wait several hours","are not hurt","have died"],"Immediate = urgent.")
H("756.d.12.F",3,"A volunteer writes names, injuries, treatment given and destination on a tag attached to each victim. This develops:","a documentation protocol for triage victims",["a grocery list","a team chant","a party plan"],"Tags track victims.")
H("756.d.12.F",4,"A triage tag should include:","the victim's condition and treatment given",["only the weather","only the time of day","only a nickname"],"Tags record patient info.")
H("756.d.13.A",3,"A volunteer performs a head-to-toe check and notes bruising, swelling and deformity. These are:","indicators of injury",["signs of fitness","signs of luck","signs of laziness"],"Look for DCAP-BTLS signs.")
H("756.d.13.A",4,"Which is an indicator of injury found during a head-to-toe assessment?","swelling or deformity",["smooth skin","a smile","clean clothes"],"Swelling and deformity signal injury.")
H("756.d.13.B",3,"A trainee sorts minor cuts from life-threatening injuries and chooses the right level of care. This distinguishes:","the severity of injuries and the appropriate response",["only color","only age","only size"],"Severity guides action.")
H("756.d.13.B",4,"A life-threatening injury, such as severe uncontrolled bleeding, should be:","treated first and EMS called",["ignored","treated last","reported later"],"Life threats come first.")
H("756.d.13.C",3,"A volunteer notes where a wound is located and what type it appears to be, then records it. This is documenting:","patient injuries, including location and type",["lunch plans","game scores","travel times"],"Documentation aids care.")
H("756.d.13.C",4,"Recording an injury's location and type helps because it:","informs later responders about care needs",["wastes time","hides information","delays care"],"Records support handoff.")
H("756.d.13.D",3,"A concussion, a neck injury and a spinal injury are examples of:","closed-head, neck or spinal injuries",["burns","bites","sprains only"],"These are serious injuries.")
H("756.d.13.D",4,"If a spinal injury is suspected, a volunteer should:","keep the person still and call for help",["move them quickly","sit them up","walk them out"],"Avoid movement.")
H("756.d.14.A",3,"A student labels the epidermis, dermis and subcutaneous layers. This defines the:","layers of skin",["bones of the leg","parts of the heart","types of muscle"],"Skin has three layers.")
H("756.d.14.A",4,"The outermost layer of skin is the:","epidermis",["dermis","subcutaneous layer","bone"],"Epidermis is outer.")
H("756.d.14.B",3,"A volunteer decides that a burn with redness only is first degree, blisters is second degree and charring is third degree. This classifies:","the severity of burns",["the size of a hose","the length of a ladder","the weight of a tank"],"Burn depth is classified by degree.")
H("756.d.14.B",4,"A burn that causes blisters is generally:","second degree",["first degree","third degree","no degree"],"Second-degree burns blister.")
H("756.d.14.C",3,"A volunteer applies direct pressure, elevates the limb and adds more dressing when blood soaks through. This is controlling:","bleeding and preventing severe blood loss",["a fire","a flood","a crowd"],"Bleeding control saves lives.")
H("756.d.14.C",4,"If blood soaks through a dressing, the volunteer should:","add another dressing on top and keep pressure",["remove it","wash it","stop pressure"],"Do not remove the first dressing.")
H("756.d.14.D",3,"A trainee rinses a minor wound with clean water and covers it with a sterile bandage. This simulates:","cleaning wounds and applying dressings and bandages",["leaving wounds open","using dirt","tying tightly"],"Clean and cover.")
H("756.d.14.D",4,"A minor wound should be covered with a:","clean, sterile dressing",["dirty cloth","plastic only","tape alone"],"Sterile cover prevents infection.")
H("756.d.14.E",3,"A volunteer finds a knife embedded in a leg and stabilizes it with padding rather than pulling it out. This is managing:","a foreign object in a wound",["a burn","a sprain","a rash"],"Do not remove embedded objects.")
H("756.d.14.E",4,"When an object is embedded in a wound, a first responder should:","leave it in place and stabilize it",["pull it out","push it deeper","twist it"],"Removal can worsen bleeding.")
H("756.d.14.F",3,"A volunteer uses padding and a rigid support to hold a broken wrist still above and below the joint. This demonstrates:","immobilization of joints",["moving joints","rubbing joints","stretching joints"],"Splints immobilize.")
H("756.d.14.F",4,"A splint should immobilize the injured bone and the joints:","above and below the injury",["only below","only at the injury","far away"],"Immobilize adjacent joints.")
H("756.d.15.A",3,"Before entering a collapsed building, a team looks at hazards, victims and resources, then forms a plan. This is to:","assess a rescue scene and formulate a plan of action",["rush in","ignore hazards","wait for a miracle"],"Size-up first.")
H("756.d.15.A",4,"The first step in a light search and rescue operation is to:","size up the situation and assess hazards",["enter immediately","call it off","ignore victims"],"Size-up precedes action.")
H("756.d.15.B",3,"Teams use cribbing and leverage to remove debris and extricate victims safely. These are:","safe techniques for debris removal and extrication",["unsafe shortcuts","random digging","guesses"],"Use safe lifting techniques.")
H("756.d.15.B",4,"When removing debris, rescuers should lift with their:","legs, keeping the back straight",["back","arms only","neck"],"Protect the back.")
H("756.d.15.C",3,"A leader gives each volunteer a role such as digging, spotting or carrying and rotates them to avoid fatigue. This creates:","a plan for assigning staff to debris removal and extrication tasks",["no plan","chaos","a vacation schedule"],"Task assignments improve safety.")
H("756.d.15.C",4,"Rotating rescuers during heavy work helps to:","reduce fatigue and injury",["increase fatigue","slow response","raise noise"],"Rotation protects teams.")
H("756.d.15.D",3,"A team gathers cribbing, shoring and ropes to stabilize unstable structures near a victim. This identifies:","materials for stabilizing hazards at an accident scene",["fun materials","cooking items","art supplies"],"Shoring and cribbing stabilize.")
H("756.d.15.D",4,"Wooden blocks stacked to support a heavy object are called:","cribbing",["tinder","kindling","shingles"],"Cribbing supports loads.")
H("756.d.15.E",3,"Before lifting a heavy beam off a victim, a team places blocks to prevent it from dropping. This describes how to:","stabilize an object prior to lifting",["lift quickly","drop the object","shake the beam"],"Stabilize before lifting.")
H("756.d.15.E",4,"Stabilizing an object before lifting helps ensure:","responder and victim safety",["more noise","less planning","greater risk"],"Prevents collapse.")
H("756.d.15.F",3,"A team uses a lever and cribbing to lift a beam a few inches, then checks the load and adjusts. This simulates a lift and:","troubleshoots possible issues",["ignores issues","adds hazards","speeds work blindly"],"Check and adjust during lifts.")
H("756.d.15.F",4,"During a lift, if the load shifts unexpectedly, rescuers should:","stop, re-stabilize and reassess",["keep lifting","walk away","add weight"],"Safety first.")
H("756.d.17.A",3,"A leader sorts tasks into those a volunteer team can do and those needing specialized units. This classifies:","response activities based on team capabilities and training",["recipes","trips","gifts"],"Know your limits.")
H("756.d.17.A",4,"A CERT team should avoid response tasks that:","exceed the team's training and capability",["match their training","are simple","are safe"],"Stay within training.")
H("756.d.17.B",3,"At a scene with a trapped victim, a team determines whether to do a light rescue or call heavy rescue units. This evaluates:","an accident scene involving a trapped victim",["a parade","a game","a party"],"Decide response level.")
H("756.d.17.B",4,"If a victim is trapped under heavy concrete, a CERT team should:","call for specialized heavy rescue",["lift it alone","ignore it","use fire"],"Heavy rescue needs specialists.")
H("756.d.17.C",3,"Using plain language and standard terms like 'victim' and 'hazard' avoids confusion on the radio. This defines:","common terminology that supports communication",["secret codes","slang","jokes"],"Clear terms prevent errors.")
H("756.d.17.C",4,"Using clear, common terminology during a response helps:","teams understand one another",["confuse others","hide plans","delay action"],"Clarity is key.")
H("756.d.17.D",3,"A leader assigns team roles such as safety officer, search team and documenter based on how big the incident is. This determines:","team member roles based on incident scope",["random roles","no roles","single roles"],"Scope shapes roles.")
H("756.d.17.D",4,"In a larger incident, a CERT team leader should:","assign clear roles and keep track of members",["do everything alone","avoid delegating","ignore members"],"Roles keep order.")
H("756.d.18.A",3,"A volunteer speaks calmly and clearly with a frightened survivor, listens and avoids jargon. This describes appropriate:","communication techniques for crises and disasters",["shouting","blame","jokes"],"Calm talk helps.")
H("756.d.18.A",4,"When speaking with a disaster survivor, a volunteer should:","speak calmly and listen actively",["interrupt","argue","blame"],"Support through listening.")
H("756.d.18.B",3,"Survivors may feel fear, anger, numbness and grief after a disaster. This explains the:","emotional responses that can follow a disaster",["physical injuries","building codes","weather"],"Emotions vary.")
H("756.d.18.B",4,"A common emotional reaction after a disaster is:","anxiety or numbness",["permanent joy","no reaction ever","loud laughter always"],"Stress reactions are common.")
H("756.d.18.C",3,"Rescuers share information, provide water and a quiet area and explain what will happen next. This identifies steps to:","reduce stressors on disaster survivors",["increase stress","hide information","hurry survivors"],"Information and comfort reduce stress.")
H("756.d.18.C",4,"One way to reduce stress for survivors is to:","keep them informed and offer basic comforts",["leave them alone","ignore questions","rush them"],"Information calms.")
H("756.d.18.D",3,"After long shifts, a rescuer shows exhaustion, irritability and difficulty sleeping. This analyzes:","psychological and physiological responses in rescuers",["signs of calm","signs of boredom","signs of fitness"],"Rescuers can be affected.")
H("756.d.18.D",4,"Prolonged rescue work can lead to rescuer symptoms such as:","fatigue and emotional strain",["new energy always","no stress","perfect memory"],"Stress and fatigue are common.")
H("756.d.18.E",3,"A survivor feels guilty for surviving while a rescuer feels overwhelmed. This describes potential:","emotional responses experienced by survivors and rescuers",["no responses","joyful events","rare events"],"Both can feel strong emotions.")
H("756.d.18.E",4,"A potential emotional response among both survivors and rescuers is:","grief or guilt",["boredom only","pride only","none"],"Grief and guilt are common.")
H("756.d.18.F",3,"On the scene, trained responders offer calm support to reduce distress and connect people to help. This explains the goals of:","on-scene psychological intervention",["ignoring people","teaching math","fixing cars"],"Aims to stabilize and support.")
H("756.d.18.F",4,"A goal of on-scene psychological support is to:","reduce distress and help people cope",["diagnose illnesses","assign blame","delay aid"],"Early support helps coping.")
H("756.d.19.A",3,"A student defines terms such as 'terrorism', 'homeland security' and 'threat'. This defines:","vocabulary related to terrorism and homeland security",["recipes","poems","sports"],"Know the vocabulary.")
H("756.d.19.A",4,"The term 'homeland security' refers to efforts to:","prevent and respond to attacks within the country",["start wars","raise taxes","run schools"],"Security protects the nation.")
H("756.d.19.B",3,"A volunteer learns to notice unattended packages, odd odors and unusual crowds as warning signs. This identifies:","environmental indicators and warning signs of terrorist activity",["signs of fun","signs of rain","signs of sale"],"Be alert and report.")
H("756.d.19.B",4,"If a CERT volunteer notices a suspicious unattended bag in a crowded place, the best action is to:","stay away and report it to authorities",["open it","kick it","move it"],"Report; do not touch.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_99.jsonl"))
